#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""一个基于 Thompson NFA（Pike 虚拟机风格）的小型正则引擎。

对外接口与 Python 的 ``re`` 模块对齐：
    compile(pattern) -> Pattern
    match(pattern, text) / search(pattern, text) -> Match | None

支持：字面量、``.``、``[...]``/``[^...]``、``\\d \\D \\w \\S`` 等字符类简写、
``\\n \\t \\r`` 转义、``* + ? {m} {m,} {m,n}`` 及其懒惰形式、
``(...)`` 分组、``|`` 交替、``^ $`` 锚点。

匹配采用 NFA 多线程模拟：每个输入位置上每个 NFA 状态至多存活一个优先级最高的
线程，因此时间复杂度为 O(文本长度 * 模式规模)，``(a+)+$`` 这类嵌套量词
不会发生指数级回溯。
"""

__all__ = ["compile", "match", "search", "Pattern", "Match", "error"]


class error(Exception):
    """正则语法错误，对标 re.error。"""


# ---------------------------------------------------------------- 解析器 ----

# AST 节点：
#   ('char', predicate)          单字符（谓词判定）
#   ('concat', [nodes...])
#   ('alt', [nodes...])
#   ('repeat', node, min, max, greedy)   max 为 None 表示无上界
#   ('group', index, node)
#   ('anchor', '^' | '$')

_DIGIT = lambda c: c.isdigit()
_WORD = lambda c: c.isalnum() or c == "_"
_SPACE = lambda c: c in " \t\n\r\f\v"
_ANY = lambda c: c != "\n"


class _Parser:
    def __init__(self, pattern):
        self.s = pattern
        self.i = 0
        self.ngroups = 0

    def parse(self):
        node = self.parse_alt()
        if self.i != len(self.s):
            raise error("意外的字符 %r（位置 %d）" % (self.s[self.i], self.i))
        return node

    def parse_alt(self):
        branches = [self.parse_concat()]
        while self.i < len(self.s) and self.s[self.i] == "|":
            self.i += 1
            branches.append(self.parse_concat())
        return branches[0] if len(branches) == 1 else ("alt", branches)

    def parse_concat(self):
        parts = []
        while self.i < len(self.s) and self.s[self.i] not in "|)":
            parts.append(self.parse_repeat())
        if not parts:
            return ("concat", [])
        return parts[0] if len(parts) == 1 else ("concat", parts)

    def parse_repeat(self):
        node = self.parse_atom()
        while self.i < len(self.s) and self.s[self.i] in "*+?{":
            ch = self.s[self.i]
            if ch == "{":
                quant = self._try_brace_quantifier()
                if quant is None:
                    break
                mn, mx = quant
            else:
                self.i += 1
                if ch == "*":
                    mn, mx = 0, None
                elif ch == "+":
                    mn, mx = 1, None
                else:
                    mn, mx = 0, 1
            greedy = True
            if self.i < len(self.s) and self.s[self.i] == "?":
                greedy = False
                self.i += 1
            node = ("repeat", node, mn, mx, greedy)
        return node

    def _try_brace_quantifier(self):
        j = self.i + 1
        start = j
        while j < len(self.s) and self.s[j].isdigit():
            j += 1
        lo_str = self.s[start:j]
        if not lo_str:
            return None
        hi_str = lo_str
        if j < len(self.s) and self.s[j] == ",":
            k = j + 1
            while k < len(self.s) and self.s[k].isdigit():
                k += 1
            hi_str = self.s[j + 1:k]
            j = k
        if j >= len(self.s) or self.s[j] != "}":
            return None
        self.i = j + 1
        lo = int(lo_str)
        hi = int(hi_str) if hi_str else None
        if hi is not None and hi < lo:
            raise error("量词区间下界大于上界: {%s}" % lo_str)
        return lo, hi

    def parse_atom(self):
        ch = self.s[self.i]
        if ch == "(":
            self.i += 1
            self.ngroups += 1
            idx = self.ngroups
            node = self.parse_alt()
            if self.i >= len(self.s) or self.s[self.i] != ")":
                raise error("分组缺少右括号")
            self.i += 1
            return ("group", idx, node)
        if ch == "[":
            return ("char", self.parse_class())
        if ch == ".":
            self.i += 1
            return ("char", _ANY)
        if ch == "^":
            self.i += 1
            return ("anchor", "^")
        if ch == "$":
            self.i += 1
            return ("anchor", "$")
        if ch in "*+?":
            raise error("量词 %r 没有可作用的对象" % ch)
        if ch == "}":
            raise error("不匹配的 }")
        if ch == "\\":
            self.i += 1
            return ("char", self.parse_escape())
        self.i += 1
        return ("char", (lambda c: c == ch))

    def parse_escape(self):
        if self.i >= len(self.s):
            raise error("字符串以孤立的反斜杠结尾")
        ch = self.s[self.i]
        self.i += 1
        simple = {
            "d": _DIGIT, "D": lambda c: not _DIGIT(c),
            "w": _WORD, "W": lambda c: not _WORD(c),
            "s": _SPACE, "S": lambda c: not _SPACE(c),
            "n": lambda c, v="\n": c == v,
            "t": lambda c, v="\t": c == v,
            "r": lambda c, v="\r": c == v,
        }
        if ch in simple:
            return simple[ch]
        return lambda c, v=ch: c == v

    def parse_class(self):
        # 调用时 self.s[self.i] == '['
        self.i += 1
        negated = False
        if self.i < len(self.s) and self.s[self.i] == "^":
            negated = True
            self.i += 1
        predicates = []
        first = True
        while first or (self.i < len(self.s) and self.s[self.i] != "]"):
            first = False
            if self.i >= len(self.s):
                raise error("字符类缺少右括号 ]")
            ch = self.s[self.i]
            if ch == "\\":
                self.i += 1
                if self.i >= len(self.s):
                    raise error("字符类中的转义不完整")
                esc = self.s[self.i]
                self.i += 1
                mapping = {
                    "d": _DIGIT, "D": lambda c: not _DIGIT(c),
                    "w": _WORD, "W": lambda c: not _WORD(c),
                    "s": _SPACE, "S": lambda c: not _SPACE(c),
                    "n": "\n", "t": "\t", "r": "\r",
                }
                if esc in ("d", "D", "w", "W", "s", "S"):
                    predicates.append(mapping[esc])
                else:
                    predicates.append(lambda c, v=esc: c == v)
            else:
                self.i += 1
                lo = ch
                # 区间 a-z
                if (self.i + 1 < len(self.s)
                        and self.s[self.i] == "-"
                        and self.s[self.i + 1] != "]"):
                    self.i += 1  # 跳过 '-'
                    hi = self.s[self.i]
                    self.i += 1
                    predicates.append(lambda c, a=lo, b=hi: a <= c <= b)
                else:
                    predicates.append(lambda c, v=lo: c == v)
        if self.i >= len(self.s):
            raise error("字符类缺少右括号 ]")
        self.i += 1  # 跳过 ']'

        if negated:
            return lambda c: c != "\n" and not any(p(c) for p in predicates)
        return lambda c: any(p(c) for p in predicates)


# --------------------------------------------------------- Thompson NFA ----
# 边表示：
#   (dst,)                       普通 epsilon 边
#   (dst, ('open', g))           进入分组
#   (dst, ('close', g))          离开分组
#   ('char', predicate, dst)     消费一个字符
#   ('assert', kind, dst)        零宽断言（^ / $）

class _NFA:
    def __init__(self):
        self.edges = []  # state -> 出边列表
        self.start = self.new_state()
        self.accept = None

    def new_state(self):
        self.edges.append([])
        return len(self.edges) - 1

    def eps(self, src, dst, tag=None):
        edge = (dst,) if tag is None else (dst, tag)
        self.edges[src].append(edge)

    def char(self, src, predicate, dst):
        self.edges[src].append(("char", predicate, dst))

    def assertion(self, src, kind, dst):
        self.edges[src].append(("assert", kind, dst))


def _build(node, nfa):
    """构造片段，返回 (start, end)。"""
    kind = node[0]
    if kind == "char":
        s, e = nfa.new_state(), nfa.new_state()
        nfa.char(s, node[1], e)
        return s, e
    if kind == "anchor":
        s, e = nfa.new_state(), nfa.new_state()
        nfa.assertion(s, node[1], e)
        return s, e
    if kind == "concat":
        items = node[1]
        if not items:
            s = e = nfa.new_state()
            return s, e
        first_s = None
        prev_e = None
        for sub in items:
            ss, ee = _build(sub, nfa)
            if first_s is None:
                first_s = ss
            if prev_e is not None:
                nfa.eps(prev_e, ss)
            prev_e = ee
        return first_s, prev_e
    if kind == "alt":
        s, e = nfa.new_state(), nfa.new_state()
        for sub in node[1]:
            ss, ee = _build(sub, nfa)
            nfa.eps(s, ss)
            nfa.eps(ee, e)
        return s, e
    if kind == "group":
        _, gidx, sub = node
        ss, ee = _build(sub, nfa)
        s, e = nfa.new_state(), nfa.new_state()
        nfa.eps(s, ss, ("open", gidx))
        nfa.eps(ee, e, ("close", gidx))
        return s, e
    if kind == "repeat":
        _, sub, mn, mx, greedy = node
        # {m,n}：先接 mn 个必选副本，再接 (mx-mn) 个可选副本，最后 * 循环
        s = nfa.new_state()
        cur = s
        for _ in range(mn):
            ss, ee = _build(sub, nfa)
            nfa.eps(cur, ss)
            cur = ee
        if mx is not None:
            for _ in range(mx - mn):
                ss, ee = _build(sub, nfa)
                skip = nfa.new_state()
                if greedy:
                    nfa.eps(cur, ss)   # 贪婪：优先继续重复
                    nfa.eps(cur, skip)
                else:
                    nfa.eps(cur, skip)  # 懒惰：优先退出
                    nfa.eps(cur, ss)
                nfa.eps(ee, skip)
                cur = skip
            e = cur
        else:
            ss, ee = _build(sub, nfa)
            entry = nfa.new_state()
            e = nfa.new_state()
            nfa.eps(cur, entry)
            if greedy:
                nfa.eps(entry, ss)  # 贪婪：循环优先
                nfa.eps(entry, e)
            else:
                nfa.eps(entry, e)   # 懒惰：退出优先
                nfa.eps(entry, ss)
            nfa.eps(ee, entry)
        return s, e
    raise error("未知 AST 节点: %r" % (kind,))


