class Match:
    def __init__(self, re, pos, endpos, groups):
        self._re = re
        self._pos = pos
        self._endpos = endpos
        self._groups = groups  # [(start, end), ...]，索引 0 为整段

    def span(self, group=0):
        return self._groups[group]

    def start(self, group=0):
        return self._groups[group][0]

    def end(self, group=0):
        return self._groups[group][1]

    def group(self, *g):
        if not g:
            s, e = self._groups[0]
            return self._re._text[s:e]
        out = []
        for idx in g:
            seg = self._groups[idx]
            out.append(None if seg is None else self._re._text[seg[0]:seg[1]])
        return out[0] if len(g) == 1 else tuple(out)

    def groups(self):
        return tuple(
            None if seg is None else self._re._text[seg[0]:seg[1]]
            for seg in self._groups[1:]
        )

    def __repr__(self):
        s, e = self._groups[0]
        return "<Match object; span=(%d, %d), match=%r>" % (
            s, e, self._re._text[s:e])


