# -*- coding: utf-8 -*-
"""A small regular expression engine (Thompson NFA), stdlib only.

Public API mirrors a subset of Python's ``re`` module:

    regex_engine.compile(pattern) -> Pattern
    regex_engine.match(pattern, text) -> Match | None
    regex_engine.search(pattern, text) -> Match | None

Supported syntax: literals, ``.``, ``[...]``/``[^...]`` classes, the
``\\d \\D \\w \\W \\s \\S`` classes and ``\\n \\t \\r`` escapes, greedy and
lazy ``* + ? {m} {m,} {m,n}`` quantifiers, ``(...)`` groups, ``|``
alternation and ``^``/``$`` anchors.

Matching runs the Thompson NFA simulation: threads are tracked as a
priority-ordered set of states, so it is worst-case linear in the text
length (times the NFA size) even on catastrophic patterns such as
``(a+)+$``.
"""

from collections import OrderedDict

__all__ = ["compile", "match", "search", "Pattern", "Match", "error"]


class error(Exception):
    """Raised for malformed regular expressions."""


# --------------------------------------------------------------------------
# Parser
# --------------------------------------------------------------------------

# Node kinds:
#   ('char', predicate)          consuming, predicate(ch) -> bool
#   ('group', node, gid)
#   ('concat', a, b)
#   ('alt', a, b)
#   ('repeat', node, mn, mx, lazy)
#   ('anchor', '^' | '$')

_DIGIT = lambda c: c.isdigit() and c.isascii()
_NONDIGIT = lambda c: not (c.isdigit() and c.isascii())
_WORD = lambda c: (c.isalnum() and c.isascii()) or c == "_"
_NONWORD = lambda c: not ((c.isalnum() and c.isascii()) or c == "_")
_SPACE = lambda c: c in " \t\n\r\f\v"
_NONSPACE = lambda c: c not in " \t\n\r\f\v"
_ANY = lambda c: c != "\n"

_SIMPLE_ESCAPES = {
    "n": "\n", "t": "\t", "r": "\r",
    "f": "\f", "v": "\v", "0": "\0", "a": "\a",
}
_CLASS_ESCAPES = {
    "d": _DIGIT, "D": _NONDIGIT,
    "w": _WORD, "W": _NONWORD,
    "s": _SPACE, "S": _NONSPACE,
}


class _Parser(object):
    def __init__(self, pattern):
        self.p = pattern
        self.i = 0
        self.ngroups = 0

    def parse(self):
        node = self._alternation()
        if self.i != len(self.p):
            raise error("unexpected %r at position %d" % (self.p[self.i], self.i))
        return node, self.ngroups

    def _alternation(self):
        node = self._concat()
        while self._peek() == "|":
            self.i += 1
            node = ("alt", node, self._concat())
        return node

    def _concat(self):
        seq = []
        while True:
            c = self._peek()
            if c is None or c == "|" or c == ")":
                break
            seq.append(self._repeat())
        if not seq:
            return ("empty",)
        node = seq[0]
        for n in seq[1:]:
            node = ("concat", node, n)
        return node

    def _repeat(self):
        node = self._atom()
        c = self._peek()
        if c in ("*", "+", "?"):
            self.i += 1
            mn = 0 if c == "*" or c == "?" else 1
            mx = None if c != "?" else 1
            lazy = False
            if self._peek() == "?":
                self.i += 1
                lazy = True
            node = ("repeat", node, mn, mx, lazy)
        elif c == "{":
            saved = self.i
            self.i += 1
            num = self._readdigits()
            mn = mx = None
            ok = False
            if num is not None:
                if self._peek() == ",":
                    self.i += 1
                    mn = num
                    num2 = self._readdigits()
                    if num2 is not None:
                        mx = num2
                    if self._peek() == "}":
                        self.i += 1
                        ok = True
                elif self._peek() == "}":
                    self.i += 1
                    mn = mx = num
                    ok = True
            if not ok:
                self.i = saved  # literal '{'
            else:
                if mx is not None and mx < mn:
                    raise error("bad repeat interval")
                lazy = False
                if self._peek() == "?":
                    self.i += 1
                    lazy = True
                node = ("repeat", node, mn, mx, lazy)
        return node

    def _readdigits(self):
        j = self.i
        while j < len(self.p) and self.p[j].isdigit():
            j += 1
        if j == self.i:
            return None
        v = int(self.p[self.i:j])
        self.i = j
        return v

    def _atom(self):
        c = self._peek()
        if c is None:
            raise error("unexpected end of pattern")
        if c == "(":
            self.i += 1
            noncap = False
            if self._peek() == "?":
                self.i += 1
                f = self._peek()
                if f == ":":
                    self.i += 1
                    noncap = True
                else:
                    raise error("bad group")
            gid = 0
            if not noncap:
                self.ngroups += 1
                gid = self.ngroups
            node = self._alternation()
            if self._peek() != ")":
                raise error("missing )")
            self.i += 1
            if noncap:
                return node
            return ("group", node, gid)
        if c == ")":
            raise error("unmatched )")
        if c == "^":
            self.i += 1
            return ("anchor", "^")
        if c == "$":
            self.i += 1
            return ("anchor", "$")
        if c == ".":
            self.i += 1
            return ("char", _ANY)
        if c == "[":
            self.i += 1
            return ("char", self._charclass())
        if c == "\\":
            return self._escape()
        if c in ("*", "+", "?"):
            raise error("nothing to repeat")
        self.i += 1
        return ("char", (lambda x: x == c))

    def _escape(self):
        self.i += 1
        c = self._peek()
        if c is None:
            raise error("bad escape at end of pattern")
        self.i += 1
        if c in _SIMPLE_ESCAPES:
            ch = _SIMPLE_ESCAPES[c]
            return ("char", (lambda x, ch=ch: x == ch))
        if c in _CLASS_ESCAPES:
            return ("char", _CLASS_ESCAPES[c])
        if c.isdigit():
            raise error("backreferences not supported")
        return ("char", (lambda x, c=c: x == c))

    def _charclass(self):
        negate = False
        if self._peek() == "^":
            negate = True
            self.i += 1
        preds = []
        literals = []
        first = True
        while True:
            c = self._peek()
            if c is None:
                raise error("unterminated character class")
            if c == "]" and not first:
                self.i += 1
                break
            first = False
            lo = self._classchar()
            if self._peek() == "-" and self.p[self.i + 1:self.i + 2] not in ("]", ""):
                self.i += 1  # '-'
                hi = self._classchar()
                if isinstance(lo, str) and isinstance(hi, str):
                    a, b = ord(lo), ord(hi)
                    if a > b:
                        raise error("bad character range")
                    preds.append(lambda x, a=a, b=b: a <= ord(x) <= b)
                else:
                    raise error("bad character range")
            elif isinstance(lo, str):
                literals.append(lo)
            else:
                preds.append(lo)
        lit = "".join(literals)

        def pred(ch):
            if ch in lit:
                return True
            for f in preds:
                if f(ch):
                    return True
            return False

        if negate:
            return lambda ch, pred=pred: not pred(ch)
        return pred

    def _classchar(self):
        c = self._peek()
        if c is None:
            raise error("unterminated character class")
        self.i += 1
        if c == "\\":
            e = self._peek()
            if e is None:
                raise error("bad escape")
            self.i += 1
            if e in _SIMPLE_ESCAPES:
                return _SIMPLE_ESCAPES[e]
            if e in _CLASS_ESCAPES:
                return _CLASS_ESCAPES[e]
            return e
        return c

    def _peek(self):
        if self.i >= len(self.p):
            return None
        return self.p[self.i]


# --------------------------------------------------------------------------
# NFA construction
#
# Fragment: (start, outs, gid_open)
#   start      - entry state id (or None for a pure empty fragment)
#   outs       - OrderedDict of dangling out slots (sid -> sid)
#   gid_open   - dict gid -> list of out slots that must close at group end
#
# State tuples:
#   ('s', sid)                     split (epsilon jump)
#   ('m', sid, sid)                epsilon with two ordered successors
#   ('c', pred, sid, gid_events)   consuming edge; events: (gid, start/end)
#   ('a', kind, sid)               anchor
# --------------------------------------------------------------------------

class _Builder(object):
    def __init__(self):
        self.states = []

    def new(self, st):
        sid = len(self.states)
        self.states.append(st)
        return sid

    def build(self, node):
        fr = self._frag(node)
        match = self.new(("end",))
        self._patch(fr, match)
        return fr[0] if fr[0] is not None else match

    def _patch(self, outs, target):
        for sid in outs:
            st = self.states[sid]
            if st[0] == "s":
                self.states[sid] = ("s", target)
            else:  # 'm'
                self.states[sid] = ("m", target, st[2])

