                    mn = mx = num
                    ok = True
            if not ok:
                self.i = saved
            else:
                if mx is not None and mx < mn:
                    raise error("bad repeat interval")
                lazy = self._consume_lazy()
                return ("repeat", node, mn, mx, lazy)
        return node

    def _consume_lazy(self):
        if self._peek() == "?":
            self.i += 1
            return True
        return False

    def _atom(self):
        c = self._peek()
        if c is None:
            raise error("unexpected end of pattern")
        if c == "(":
            self.i += 1
            gid = 0
            if self._peek() == "?":
                self.i += 1
                if self._peek() != ":":
                    raise error("bad group")
                self.i += 1
            else:
                self.ngroups += 1
                gid = self.ngroups
            node = self._alternation()
            if self._peek() != ")":
                raise error("missing )")
            self.i += 1
            return node if gid == 0 else ("group", node, gid)
        if c == ")":
            raise error("unmatched )")
        if c == "^":
            self.i += 1
            return ("anchor", "^")
        if c == "$":
            self.i += 1
            return ("anchor", "$")
        if c == ".":
            self.i += 1
            return ("char", _ANY)
        if c == "[":
            self.i += 1
            return ("char", self._charclass())
        if c == "\\":
            return self._escape()
        if c in ("*", "+", "?"):
            raise error("nothing to repeat")
        self.i += 1
        return ("char", lambda x, c=c: x == c)

    def _escape(self):
        self.i += 1
        c = self._peek()
        if c is None:
            raise error("bad escape at end of pattern")
        self.i += 1
        if c in _SIMPLE_ESCAPES:
            ch = _SIMPLE_ESCAPES[c]
            return ("char", lambda x, ch=ch: x == ch)
        if c in _CLASS_ESCAPES:
            return ("char", _CLASS_ESCAPES[c])
        if c.isdigit():
            raise error("backreferences are not supported")
        return ("char", lambda x, c=c: x == c)

    def _classchar(self):
        """Return either a literal character or a predicate."""
        c = self._peek()
        if c is None:
            raise error("unterminated character class")
        self.i += 1
        if c == "\\":
            e = self._peek()
            if e is None:
                raise error("bad escape")
            self.i += 1
            if e in _SIMPLE_ESCAPES:
                return _SIMPLE_ESCAPES[e]
            if e in _CLASS_ESCAPES:
                return _CLASS_ESCAPES[e]
            return e
        return c

    def _charclass(self):
        negate = False
        if self._peek() == "^":
            negate = True
            self.i += 1
        literals = []
        ranges = []
        preds = []
        first = True
        while True:
            c = self._peek()
            if c is None:
                raise error("unterminated character class")
            if c == "]" and not first:
                self.i += 1
                break
            first = False
            lo = self._classchar()
            if self._peek() == "-" and self._peek(1) not in (None, "]"):
                self.i += 1  # '-'
                hi = self._classchar()
                if not (isinstance(lo, str) and isinstance(hi, str)):
                    raise error("bad character range")
                a, b = ord(lo), ord(hi)
                if a > b:
                    raise error("bad character range")
                ranges.append((a, b))
            elif isinstance(lo, str):
                literals.append(lo)
            else:
                preds.append(lo)
        lit = "".join(literals)

        def member(ch):
            if ch in lit:
                return True
            o = ord(ch)
            for a, b in ranges:
                if a <= o <= b:
                    return True
            for f in preds:
                if f(ch):
                    return True
            return False

        if negate:
            return lambda ch: not member(ch)
        return member

