# A thread is (state_id, caps) where caps is a tuple of (start, end) pairs
# per group (None for unmatched groups).  Threads are added in strict priority
# order (the order successor slots appear in) and de-duplicated by state:
# the first thread reaching a state keeps its captures, matching Python re's
# leftmost-greedy semantics.
# --------------------------------------------------------------------------


class _Runner(object):
    def __init__(self, nfa, text):
        self.nfa = nfa
        self.states = nfa.states
        self.text = text
        self.n = len(text)

    def _anchor_ok(self, kind, pos):
        if kind == "^":
            return pos == 0
        if pos == self.n:
            return True
        return pos == self.n - 1 and self.text[pos] == "\n"

    def _add(self, clist, seen, gen, sid, caps, pos):
        """Epsilon-close thread (sid, caps), appending to clist in order."""
        stack = [(sid, caps)]
        while stack:
            cur, ccaps = stack.pop()
            st = self.states[cur]
            tag = st[0]
            if tag == "ep":
                if seen.get(cur) == gen:
                    continue
                seen[cur] = gen
                succs = st[1]
                # push in reverse so the first successor is processed first
                for j in range(len(succs) - 1, -1, -1):
                    nxt = succs[j]
                    if isinstance(nxt, list):
                        nxt = nxt[0]
                    if nxt is not None:
                        stack.append((nxt, ccaps))
            elif tag == "mark":
                name, gid = st[1]
                idx = (gid - 1) * 2 + (0 if name == "gstart" else 1)
                ccaps = ccaps[:idx] + (pos,) + ccaps[idx + 1:]
                nxt = st[2][0]
                if isinstance(nxt, list):
                    nxt = nxt[0]
                if nxt is not None:
                    stack.append((nxt, ccaps))
            elif tag == "a":
                if seen.get(cur) == gen:
                    continue
                seen[cur] = gen
                if self._anchor_ok(st[1], pos):
                    nxt = st[2][0]
                    if nxt is not None:
                        stack.append((nxt, ccaps))
            elif tag == "end":
                if seen.get(cur) != gen:
                    seen[cur] = gen
                    clist.append((cur, ccaps))
            else:  # 'c' consuming state
                if seen.get(cur) != gen:
                    seen[cur] = gen
                    clist.append((cur, ccaps))

    def run_from(self, start_pos):
        """Try matching starting at start_pos. Return end position or -1."""
        caps = (None,) * (self.nfa.ngroups * 2)
        clist = []
        seen = {}
        nlist = []
